      "stride": "InformationDisclosure",
      "title": "Device backups contain delivery addresses",
      "scenario": "An attacker who gains access to the user's cloud backups (via password reuse, social engineering, or cloud service compromise) or physical computer backups can extract notification data containing historical delivery addresses",
      "component": "Device backup system",
      "likelihood": 2,
      "impact": 3,
